28	/**
29	 * Matrix multiplication: C = A * B.
30	 *
31	 * This sample demonstrates implements matrix multiplication which makes use of shared memory
32	 * to ensure data reuse, the matrix multiplication is done using tiling approach.
33	 * With compute capability 8.0 or higher the CUDA kernels involved uses asynchronously copy data
34	 * from global to shared memory; a.k.a., async-copy.
35	 * This sample has been written for clarity of exposition to illustrate various CUDA programming
36	 * principles, not with the goal of providing the most performant generic kernel for matrix multiplication.
37	 */
38	
39	// System includes
40	#include <stdio.h>
41	#include <assert.h>
42	
43	// CUDA runtime
44	#include <cuda_runtime.h>
45	#include <cuda_pipeline.h>
46	#if __CUDA_ARCH__ >= 700
47	#include <cuda_awbarrier.h>
48	#endif
49	
50	// Helper functions and utilities to work with CUDA
51	#include <helper_functions.h>
52	#include <helper_cuda.h>
53	
54	namespace nvcuda_namespace = nvcuda::experimental;
55	
56	enum kernels
57	{
58	    AsyncCopyMultiStageLargeChunk = 0,
59	    AsyncCopyLargeChunk           = 1,
60	    AsyncCopyLargeChunkAWBarrier  = 2,
61	    AsyncCopyMultiStage           = 3,
62	    AsyncCopySingleStage          = 4,
63	    Naive                         = 5,
64	    NaiveLargeChunk               = 6
65	};
66	
67	const char* kernelNames[] = {"AsyncCopyMultiStageLargeChunk", "AsyncCopyLargeChunk", 
68	                            "AsyncCopyLargeChunkAWBarrier", "AsyncCopyMultiStage", 
69	                            "AsyncCopySingleStage", "Naive", "NaiveLargeChunk"};
70	
71	#define USE_CPP_API 0
72	
73	constexpr int blockSize = 16;
74	
75	// Multi Stage memcpy_async pipeline with large chunk copy
76	template <int BLOCK_SIZE> __global__ void MatrixMulAsyncCopyMultiStageLargeChunk(float* __restrict__ C, 
77	                                                        const float* __restrict__ A,
78	                                                        const float* __restrict__ B, int wA,
79	                                                        int wB) {
80	    // Requires BLOCK_SIZE % 4 == 0 
81	
82	    // Multi-stage pipeline version
83	    constexpr size_t maxPipelineStages = 4;
84	
85	    // Declaration of the shared memory array As used to
86	    // store the sub-matrix of A for each stage
87	    __shared__ float As[maxPipelineStages][BLOCK_SIZE][BLOCK_SIZE];
88	
89	    // Declaration of the shared memory array Bs used to
90	    // store the sub-matrix of B for each stage
91	    __shared__ float Bs[maxPipelineStages][BLOCK_SIZE][BLOCK_SIZE];
92	
93	    float Csub = 0.0;
94	
95	    // Index of the first sub-matrix of A processed by the block
96	    const int aBegin = wA * (BLOCK_SIZE) * blockIdx.y;
97	
98	    // Index of the last sub-matrix of A processed by the block
99	    const int aEnd   = aBegin + wA - 1;
100	
101	    // Step size used to iterate through the sub-matrices of A
102	    int aStep  = BLOCK_SIZE;
103	
104	    // Index of the first sub-matrix of B processed by the block
105	    const int bBegin = BLOCK_SIZE * blockIdx.x;
106	
107	    // Step size used to iterate through the sub-matrices of B
108	    int bStep  = BLOCK_SIZE * wB;
109	
110	    const int t4x = threadIdx.x * 4 ;
111	
112	#if USE_CPP_API
113	    nvcuda_namespace::pipeline pipe;
114	#endif
115	    // Loop over all the sub-matrices of A and B
116	    // required to compute the block sub-matrix
117	    for (int a = aBegin, b = bBegin, i = 0, aStage = aBegin, bStage = bBegin, iStage = 0; a <= aEnd; a += aStep, b += bStep, ++i ) {
118	        // Load the matrices from device memory to shared memory; each thread loads
119	        // one element of each matrix
120	
121	        for ( ; aStage <= a + aStep * maxPipelineStages ; aStage += aStep, bStage += bStep, ++iStage )
122	        {
123	            if ( aStage <= aEnd && t4x < BLOCK_SIZE )
124	            {
125	                // Rotating buffer
126	                const int j = iStage % maxPipelineStages;
127	                float4 * const A4s = reinterpret_cast<float4*>(& As[j][threadIdx.y][t4x]);
128	                float4 * const B4s = reinterpret_cast<float4*>(& Bs[j][threadIdx.y][t4x]);
129	                const float4 * const A4  = reinterpret_cast<const float4*>(& A[aStage + wA * threadIdx.y + t4x]);
130	                const float4 * const B4  = reinterpret_cast<const float4*>(& B[aStage + wA * threadIdx.y + t4x]);
131	
132	#if USE_CPP_API
133	                nvcuda_namespace::memcpy_async(*A4s,*A4, pipe);
134	                nvcuda_namespace::memcpy_async(*B4s,*B4, pipe);
135	#else
136	                __pipeline_memcpy_async(A4s, A4, sizeof(float4));
137	                __pipeline_memcpy_async(B4s, B4, sizeof(float4));
138	#endif
139	            }
140	
141	#if USE_CPP_API
142	            pipe.commit();
143	#else
144	            __pipeline_commit();
145	#endif
146	        }
147	#if USE_CPP_API
148	        pipe.wait_prior<maxPipelineStages-1>();
149	#else
150	        __pipeline_wait_prior(maxPipelineStages-1);
151	#endif
152	        // Synchronize to make sure the matrices are loaded
153	        __syncthreads();
154	
155	        // Rotating buffer
156	        const int j = i % maxPipelineStages;
157	
158	        // Multiply the two matrices together;
159	        // each thread computes one element
160	        // of the block sub-matrix
161	        for (int k = 0; k < BLOCK_SIZE; ++k) {
162	            Csub += As[j][threadIdx.y][k] * Bs[j][k][threadIdx.x];
163	        }
164	
165	        // Don't have to synchronize because 
166	        // next iteration is loading to a different buffer
167	    }
168	
169	    // Write the block sub-matrix to device memory;
170	    // each thread writes four element
171	    int c = wB * BLOCK_SIZE * blockIdx.y + BLOCK_SIZE * blockIdx.x;
172	    C[c + wB * threadIdx.y + threadIdx.x] = Csub;
173	}
