176	template <int BLOCK_SIZE> __global__ void MatrixMulAsyncCopyLargeChunk(float* __restrict__ C, 
177	                                                        const float* __restrict__ A,
178	                                                        const float* __restrict__ B, int wA,
179	                                                        int wB) {
180	    // Requires BLOCK_SIZE % 4 == 0 
181	
182	    // Declaration of the shared memory array As used to
183	    // store the sub-matrix of A
184	    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
185	
186	    // Declaration of the shared memory array Bs used to
187	    // store the sub-matrix of B
188	    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];
189	
190	    // Index of the first sub-matrix of A processed by the block
191	    int aBegin = wA * BLOCK_SIZE * blockIdx.y;
192	
193	    // Index of the last sub-matrix of A processed by the block
194	    int aEnd   = aBegin + wA - 1;
195	
196	    // Step size used to iterate through the sub-matrices of A
197	    int aStep  = BLOCK_SIZE;
198	
199	    // Index of the first sub-matrix of B processed by the block
200	    int bBegin = BLOCK_SIZE * blockIdx.x;
201	
202	    // Step size used to iterate through the sub-matrices of B
203	    int bStep  = BLOCK_SIZE * wB;
204	
205	    // Single-stage pipeline version
206	    float Csub = 0.0;
207	
208	    const int t4x = threadIdx.x * 4;
209	#if USE_CPP_API
210	    nvcuda_namespace::pipeline pipe;
211	#endif
212	    // Loop over all the sub-matrices of A and B
213	    // required to compute the block sub-matrix
214	    for (int a = aBegin, b = bBegin; a <= aEnd; a += aStep, b += bStep) {
215	        // Load the matrices from device memory to shared memory; 
216	        // a subset of threads loads a contiguous chunk of elements.
217	
218	        // Previously, per-thread:
219	        // As[ty][tx] = A[a + wA * ty + tx];
220	        // Bs[ty][tx] = B[b + wB * ty + tx];
221	
222	        // Now, one fourth of the threads load four elements of each matrix
223	        if ( t4x < BLOCK_SIZE ) {
224	            float4 * const A4s = reinterpret_cast<float4*>(& As[threadIdx.y][t4x]);
225	            float4 * const B4s = reinterpret_cast<float4*>(& Bs[threadIdx.y][t4x]);
226	            const float4 * const A4  = reinterpret_cast<const float4*>(& A[a + wA * threadIdx.y + t4x]);
227	            const float4 * const B4  = reinterpret_cast<const float4*>(& B[a + wA * threadIdx.y + t4x]);
228	
229	#if USE_CPP_API
230	            nvcuda_namespace::memcpy_async(*A4s,*A4,pipe);
231	            nvcuda_namespace::memcpy_async(*B4s,*B4,pipe);
232	
233	            pipe.commit_and_wait();
234	#else
235	            __pipeline_memcpy_async(A4s, A4, sizeof(float4));
236	            __pipeline_memcpy_async(B4s, B4, sizeof(float4));
237	
238	            __pipeline_commit();
239	            __pipeline_wait_prior(0);
240	#endif
241	        }
242	
243	        // Synchronize to make sure the matrices are loaded
244	        __syncthreads();
245	
246	        // Multiply the two matrices together;
247	        // each thread computes one element
248	        // of the block sub-matrix
249	#pragma unroll
250	        for (int k = 0; k < BLOCK_SIZE; ++k) {
251	            Csub += As[threadIdx.y][k] * Bs[k][threadIdx.x];
252	        }
253	
254	        // Synchronize to make sure that the preceding
255	        // computation is done before loading two new
256	        // sub-matrices of A and B in the next iteration
257	        __syncthreads();
258	    }
259	
260	    // Write the block sub-matrix to device memory;
261	    // each thread writes four element
262	    int c = wB * BLOCK_SIZE * blockIdx.y + BLOCK_SIZE * blockIdx.x;
263	    C[c + wB * threadIdx.y + threadIdx.x] = Csub;
264	}
